with valid_subscriptions as (select * from subscriptions where status in ('CANCELLED', 'PAUSED', 'EXPIRED') and start_date > '2023-08-24' and monthly_fee <= 230), agg as (select case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end as start_cohort, year(start_date) as start_year, sort_array(collect_set(status)) as status_list, count(case when plan = 'premium' then 1 end) as premium_count from valid_subscriptions group by case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end, year(start_date)) select start_cohort, start_year, status_list, premium_count from agg order by start_cohort;
